mapper.select:
SELECT , c.SNAME AS CATE_NM, GET_FULL_NAME_BY_CATE_NO('NONE', p.ICATE_NO) AS CATE_FULL_NM, b.ORGNZT_NM AS BUSEO_NM FROM TB_PROM p LEFT OUTER JOIN TB_CATE c ON p.ICATE_NO = c.ICATE_NO LEFT OUTER JOIN COMTNORGNZTINFO b ON b.ORGNZT_ID = COALESCE(p.SBUSEO_ORGNZT_ID, 'ORG_' || LPAD(CAST(p.IBUSEO_NO AS text), 16, '0')) WHERE p.SEXISTING_YN = 'Y'
AND p.ICATE_NO = #{cateNo}
AND p.SGUBUN_ID = #{gubunId}
AND UPPER(p.STITLE) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND STRPOS(p.SSEARCH_TEXT, #{searchKeyword}) > 0
AND UPPER(c.SNAME) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND UPPER(b.ORGNZT_NM) LIKE '%' || UPPER(#{searchKeyword}) || '%'
AND UPPER(p.STITLE) LIKE '%' || UPPER(#{searchKeyword}) || '%'
ORDER BY p.ISEQ, p.SORDERIDX, p.IPROM_NO DESC LIMIT #{recordCountPerPage} OFFSET #{firstIndex}

SELECT ICATE_NO FROM (
	SELECT p.ICATE_NO
	  FROM TB_PROM p
	 WHERE p.ILAW_ID = #{lawId}
	 ORDER BY p.ILAW_NO DESC, p.IPROM_NO DESC
) X LIMIT 1

